WEIGHT_MODES = ("uniform", "ICRP", "response", "dose")
LOG_EPS = 1e-20   # floor inside log(phi + LOG_EPS) for the log-RMSE

def configure_openmc_cross_sections(hpc: bool) -> None:
    import openmc

    env = "hpc" if hpc else "local"
    cross_sections = os.environ.get("OPENMC_CROSS_SECTIONS", CROSS_SECTIONS[env])
    openmc.config["cross_sections"] = os.path.expanduser(cross_sections)

    chain_file = os.environ.get("OPENMC_CHAIN_FILE", CHAIN_FILE[env])
    if chain_file:
        openmc.config["chain_file"] = os.path.expanduser(chain_file)


def _gaussian_std(fwhm, std) -> float:
    if (fwhm is None) == (std is None):
        raise ValueError(
            "Set one of SOURCE_GAUSSIAN['fwhm'] or SOURCE_GAUSSIAN['std'] "
            "(leave the other as None)."
        )
    if std is not None:
        return float(std)
    return float(fwhm) / (2.0 * math.sqrt(2.0 * math.log(2.0)))


def _gaussian_histogram(mean, std, n_bins, n_sigma):
    if std <= 0.0:
        raise ValueError("Gaussian standard deviation must be > 0")
    lo = max(0.0, mean - n_sigma * std)
    hi = mean + n_sigma * std
    edges = np.linspace(lo, hi, n_bins + 1)
    z = (edges - mean) / (math.sqrt(2.0) * std)
    cdf = 0.5 * (1.0 + np.vectorize(math.erf)(z))
    return edges, np.diff(cdf)


def build_source_spectrum():
    """Return (edges, bin-integrated content) for the active SOURCE_KIND."""
    if SOURCE_KIND == "gaussian":
        g = SOURCE_GAUSSIAN
        std = _gaussian_std(g.get("fwhm"), g.get("std"))
        return _gaussian_histogram(g["mean"], std, g["n_bins"], g["n_sigma"])
    if SOURCE_KIND == "edges":
        h = SOURCE_HISTOGRAM
        edges = np.asarray(h["edges"], float)
        values = np.asarray(h["values"], float)
        if edges.size != values.size + 1:
            raise ValueError(
                "SOURCE_HISTOGRAM['values'] must have one entry per bin "
                f"(len(edges)-1 = {edges.size - 1}, got {values.size})."
            )
        content = values * np.diff(edges) if h["values_are_density"] else values
        return edges, content
    raise ValueError(
        f"Unknown SOURCE_KIND {SOURCE_KIND!r}; use 'gaussian' or 'edges'."
    )


SOURCE_EDGES, SOURCE_VALUES = build_source_spectrum()
